import pandas as pd

def parse_date(s):
    for fmt in [None, '%B %d, %Y at %I:%M %p', '%d %b %Y, %H:%M', '%Y-%m-%d %H:%M:%S']:
        try:
            if fmt is None:
                d = pd.to_datetime(s, errors='raise')
            else:
                d = pd.to_datetime(s, format=fmt, errors='raise')
            return d
        except Exception:
            continue
    return pd.NaT

