import ast

def truthy(v):
    if v is True:
        return True
    if isinstance(v, str) and v.strip() in ('True', 'true'):
        return True
    return False

def parse_bp(v):
    if v is None:
        return {}
    if isinstance(v, dict):
        return v
    if isinstance(v, str):
        try:
            r = ast.literal_eval(v)
            if isinstance(r, dict):
                return r
        except Exception:
            pass
        # fallback: substring scan
        return {'_raw': 'True' if 'True' in v else 'False'}
    return {}

qualifies = []
bike_only = business_only = both = 0
for d in docs:
    attrs = d.get('attributes')
    if not attrs:
        continue
    bike = truthy(attrs.get('BikeParking'))
    bp = parse_bp(attrs.get('BusinessParking'))
    biz_park = any(truthy(v) for v in bp.values())
    if bike or biz_park:
        qualifies.append(d['business_id'])
        if bike and biz_park: both += 1
        elif bike: bike_only += 1
        else: business_only += 1

print("qualifying count:", len(qualifies))
